package com.csi;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.Authentication;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.util.*;
@RestController public class ApiController {
 final Db db;final Events events;final PolicyCatalog catalog;final Set<String> allowed;
 static final String SCANS="SELECT s.*, (SELECT count(*) FROM findings f WHERE f.scan_id=s.id) finding_count, (SELECT coalesce(jsonb_agg(DISTINCT severity),'[]') FROM findings f WHERE f.scan_id=s.id) severities FROM scans s ";
 static final String FINDINGS="SELECT f.*,e.masked_code_evidence,s.repository,s.commit_sha,s.policy_version FROM findings f JOIN scans s ON s.id=f.scan_id JOIN finding_evidences e ON e.finding_id=f.id ";
 public ApiController(Db db,Events events,PolicyCatalog catalog,@Value("${csi.repository-allowlist}")String allow){this.db=db;this.events=events;this.catalog=catalog;allowed=Set.of(allow.split(","));}
 @GetMapping("/api/health") public Map<String,String> health(){return Map.of("status","UP");}
 @GetMapping("/api/projects") public Object projects(){return db.list("SELECT p.*,pp.version policy_version,s.status latest_status,s.created_at last_scan_at,(SELECT count(*) FROM findings f WHERE f.scan_id=s.id) finding_count FROM projects p JOIN project_policies pp ON pp.project_id=p.id LEFT JOIN LATERAL (SELECT * FROM scans WHERE project_id=p.id ORDER BY created_at DESC LIMIT 1) s ON true ORDER BY p.created_at DESC");}
 @GetMapping("/api/projects/{id}") public Object project(@PathVariable UUID id){return db.one("SELECT p.*,pp.version policy_version FROM projects p JOIN project_policies pp ON pp.project_id=p.id WHERE p.id=?",id);}
 public record NewProject(String repository,String defaultBranch){}
 @PostMapping("/api/projects") @Transactional public Object project(@RequestBody NewProject p){if(p.repository()==null||!p.repository().matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+")||!allowed.contains(p.repository()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Repository Allowlist를 확인하세요.");if(p.defaultBranch()==null||!p.defaultBranch().matches("[A-Za-z0-9_./-]{1,100}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"유효하지 않은 브랜치입니다.");UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO projects(id,repository,default_branch) VALUES(?,?,?)",id,p.repository(),p.defaultBranch());db.jdbc.update("INSERT INTO project_policies VALUES(?,?,?::jsonb)",id,catalog.policy.get("version"),db.encode(catalog.policy));return Map.of("id",id);}
 @GetMapping("/api/scans") public Object scans(@RequestParam(required=false)UUID projectId){return projectId==null?db.list(SCANS+"ORDER BY created_at DESC LIMIT 1000"):db.list(SCANS+"WHERE project_id=? ORDER BY created_at DESC LIMIT 1000",projectId);}
 @GetMapping({"/api/scans/{id}","/internal/scans/{id}"}) public Object scan(@PathVariable UUID id){return db.one(SCANS+"WHERE s.id=?",id);}
 @GetMapping({"/api/scans/{id}/findings","/internal/scans/{id}/findings"}) public Object scanFindings(@PathVariable UUID id){db.one("SELECT id FROM scans WHERE id=?",id);return db.list(FINDINGS+"WHERE scan_id=? ORDER BY start_line",id);}
 @GetMapping("/api/findings") public Object findings(){return db.list(FINDINGS+"ORDER BY s.created_at DESC,f.start_line LIMIT 1000");}
 @GetMapping("/api/findings/{id}") public Object finding(@PathVariable UUID id){var f=db.one(FINDINGS+"WHERE f.id=?",id);f.put("activity",db.list("SELECT * FROM finding_activity WHERE finding_id=? ORDER BY timestamp DESC",id));return f;}
 @GetMapping("/api/scans/{id}/logs") public Object logs(@PathVariable UUID id){return db.list("SELECT * FROM scan_logs WHERE scan_id=? ORDER BY timestamp",id);}
 @GetMapping("/api/logs") public Object logs(Authentication a){db.log(null,"LOG_ACCESS","backend","INFO","Audit logs viewed by security reviewer");return db.list("SELECT * FROM scan_logs ORDER BY timestamp DESC LIMIT 1000");}
 @GetMapping("/api/policies") public Object policies(){return catalog.catalog;}
 @GetMapping("/internal/scans/{id}/policy") public Object policy(@PathVariable UUID id){return db.one("SELECT policy FROM scans WHERE id=?",id).get("policy");}
 @GetMapping("/internal/scans/{id}/history") public Object history(@PathVariable UUID id){return db.list(SCANS+"WHERE project_id=(SELECT project_id FROM scans WHERE id=?) ORDER BY created_at DESC LIMIT 10",id);}
 @GetMapping("/api/scans/{id}/comparison") public Object comparison(@PathVariable UUID id){var rows=db.list("SELECT p.id FROM scans p JOIN scans c ON p.project_id=c.project_id AND p.branch=c.branch WHERE c.id=? AND p.created_at<c.created_at AND p.status='COMPLETED' ORDER BY p.created_at DESC LIMIT 1",id);Set<String> now=new HashSet<>();db.list("SELECT fingerprint FROM findings WHERE scan_id=?",id).forEach(f->now.add((String)f.get("fingerprint")));Set<String> old=new HashSet<>();if(!rows.isEmpty())db.list("SELECT fingerprint FROM findings WHERE scan_id=?",UUID.fromString((String)rows.getFirst().get("id"))).forEach(f->old.add((String)f.get("fingerprint")));Set<String> added=new HashSet<>(now);added.removeAll(old);Set<String> removed=new HashSet<>(old);removed.removeAll(now);return Map.of("previousScanId",rows.isEmpty()?"":rows.getFirst().get("id"),"added",added.size(),"removed",removed.size(),"unchanged",now.size()-added.size());}
 @GetMapping(value="/api/scans/{id}/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter stream(@PathVariable UUID id){db.one("SELECT id FROM scans WHERE id=?",id);return events.subscribe(id.toString());}
 @GetMapping(value="/api/events/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter stream(){return events.subscribe(null);}
 public record Review(String status){}
 @PostMapping("/api/findings/{id}/review") @Transactional public Object review(@PathVariable UUID id,@RequestBody Review r){if(!Set.of("OPEN","REVIEWING","RESOLVED").contains(r.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);var f=db.one("SELECT scan_id FROM findings WHERE id=?",id);db.jdbc.update("UPDATE findings SET status=? WHERE id=?",r.status(),id);db.jdbc.update("INSERT INTO finding_activity VALUES(?,?,now(),?)",UUID.randomUUID(),id,"Reviewer changed status to "+r.status());events.publish((String)f.get("scanId"));return Map.of("status",r.status());}
 static final String APPROVALS="SELECT a.*,s.repository,s.commit_sha,s.policy_version FROM approvals a JOIN scans s ON s.id=a.scan_id ";
 @GetMapping("/api/approvals") public Object approvals(){return db.list(APPROVALS+"ORDER BY a.created_at DESC");}
 @GetMapping("/internal/approvals/{id}") public Object approval(@PathVariable UUID id){return db.one(APPROVALS+"WHERE a.id=?",id);}
 @GetMapping("/internal/scans/{id}/approval") public Object scanApproval(@PathVariable UUID id){return db.one(APPROVALS+"WHERE a.scan_id=?",id);}
 public record Decision(String decision){}
 @PostMapping("/api/approvals/{id}/decision") @Transactional public Object decision(@PathVariable UUID id,@RequestBody Decision d,Authentication a){if(!Set.of("APPROVED","REJECTED").contains(d.decision()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);var row=db.one("SELECT * FROM approvals WHERE id=? FOR UPDATE",id);if(!row.get("status").equals("PENDING"))throw new ResponseStatusException(HttpStatus.CONFLICT,"이미 처리된 요청입니다.");UUID scanId=UUID.fromString((String)row.get("scanId"));db.jdbc.update("UPDATE approvals SET status=?,decided_by=?,decided_at=now() WHERE id=?",d.decision(),a.getName(),id);db.jdbc.update("UPDATE agent_checkpoints SET state='RESUME_QUEUED',updated_at=now() WHERE scan_id=?",scanId);db.log(scanId,"APPROVAL_DECIDED","backend","INFO",d.decision());enqueue(scanId,"APPROVAL_DECIDED");events.publish(scanId.toString());return Map.of("status",d.decision());}
 @PostMapping("/internal/scans/{id}/review-request") @Transactional public Object request(@PathVariable UUID id){db.one("SELECT id FROM scans WHERE id=?",id);db.jdbc.update("INSERT INTO approvals(id,scan_id,action) VALUES(?,?,'CREATE_SECURITY_REVIEW_ISSUE') ON CONFLICT(scan_id) DO NOTHING",UUID.randomUUID(),id);db.jdbc.update("INSERT INTO agent_checkpoints VALUES(?,?,'WAITING_APPROVAL',now()) ON CONFLICT(scan_id) DO UPDATE SET state='WAITING_APPROVAL',updated_at=now()",id,id.toString());return scanApproval(id);}
 @PostMapping("/internal/approvals/{id}/issue") @Transactional public Object issue(@PathVariable UUID id){var row=db.one("SELECT * FROM approvals WHERE id=? FOR UPDATE",id);if(!Set.of("APPROVED","EXECUTED").contains(row.get("status")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"승인되지 않은 작업입니다.");UUID scan=UUID.fromString((String)row.get("scanId"));db.jdbc.update("INSERT INTO security_issues VALUES(?,?,?,now()) ON CONFLICT(approval_id) DO NOTHING",UUID.randomUUID(),id,scan);db.jdbc.update("UPDATE approvals SET status='EXECUTED' WHERE id=?",id);db.jdbc.update("UPDATE agent_checkpoints SET state='FINALIZED',updated_at=now() WHERE scan_id=?",scan);db.log(scan,"ISSUE_CREATED","business-mcp","INFO","Approved internal security review issue recorded");events.publish(scan.toString());return db.one("SELECT * FROM security_issues WHERE approval_id=?",id);}
 public boolean isAllowed(String repository){return allowed.contains(repository);}
 public void enqueue(UUID scan,String type){var s=db.one("SELECT * FROM scans WHERE id=?",scan);UUID eid=UUID.randomUUID();var payload=new LinkedHashMap<String,Object>();payload.put("eventId",eid);payload.put("scanId",scan);payload.put("projectId",s.get("projectId"));payload.put("repository",s.get("repository"));payload.put("commitSha",s.get("commitSha"));payload.put("timestamp",java.time.Instant.now().toString());payload.put("eventType",type);payload.put("correlationId",scan);db.jdbc.update("INSERT INTO event_outbox(id,scan_id,topic,payload) VALUES(?,?,?,?::jsonb)",eid,scan,"scan.request",db.encode(payload));}
 @GetMapping("/api/dashboard/overview") public Object overview(){var m=new LinkedHashMap<String,Object>();String latest="f.scan_id IN (SELECT DISTINCT ON(project_id,branch) id FROM scans WHERE status='COMPLETED' ORDER BY project_id,branch,created_at DESC)";m.put("projects",db.count("SELECT count(*) FROM projects"));m.put("completedScans",db.count("SELECT count(*) FROM scans WHERE status='COMPLETED'"));m.put("openFindings",db.count("SELECT count(*) FROM findings f WHERE status<>'RESOLVED' AND "+latest));m.put("criticalHigh",db.count("SELECT count(*) FROM findings f WHERE status<>'RESOLVED' AND severity IN ('CRITICAL','HIGH') AND "+latest));m.put("pendingApprovals",db.count("SELECT count(*) FROM approvals WHERE status='PENDING'"));m.put("distribution",db.list("SELECT severity,count(*) count FROM findings f WHERE status<>'RESOLVED' AND "+latest+" GROUP BY severity"));m.put("trend",db.list("SELECT to_char(s.created_at AT TIME ZONE 'Asia/Seoul','MM-DD') AS day,count(f.id) count FROM scans s LEFT JOIN findings f ON f.scan_id=s.id WHERE s.created_at>now()-interval '14 days' GROUP BY 1 ORDER BY min(s.created_at)"));m.put("recentScans",db.list(SCANS+"ORDER BY created_at DESC LIMIT 5"));m.put("recentLogs",db.list("SELECT * FROM scan_logs ORDER BY timestamp DESC LIMIT 4"));m.put("repositoryRisk",db.list("SELECT p.id,p.repository,count(f.id) count FROM projects p LEFT JOIN scans s ON s.project_id=p.id LEFT JOIN findings f ON f.scan_id=s.id AND f.status<>'RESOLVED' AND "+latest+" GROUP BY p.id ORDER BY count DESC"));m.put("failures",db.list(SCANS+"WHERE status='FAILED' ORDER BY created_at DESC LIMIT 5"));m.put("topFindings",db.list(FINDINGS+"WHERE f.status<>'RESOLVED' AND "+latest+" ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END LIMIT 5"));return m;}
}
